import Link from "next/link";
import { ArrowLeft, Camera, ScanLine } from "lucide-react";
import BriefingConfidenceAnchor from "../components/briefings/BriefingConfidenceAnchor";
import ActionButton from "../components/ui/ActionButton";
import Card from "../components/ui/Card";
import IconBadge from "../components/ui/IconBadge";

export default function DEXAEventBriefingScreen({ narrative, phaseReview = null, preview = false }) {
  if (!hasCompleteDexaNarrative(narrative)) {
    return <main className="app-surface mx-auto min-h-screen max-w-[393px] overflow-x-hidden"><div className="px-4 pb-32 pt-10"><Link className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-slate-500" href={preview ? "/progress/dexa" : "/briefings/review"}><ArrowLeft size={18}/>Back</Link><Card><Eyebrow>DEXA Event Briefing</Eyebrow><h1 className="mt-2 text-xl font-extrabold text-slate-950">This historical briefing is unavailable.</h1><p className="mt-2 text-sm font-semibold leading-6 text-slate-600">Its saved DEXA snapshot is incomplete. Reprocess the source scan before using this briefing for decisions.</p></Card></div></main>;
  }
  const { hero, snapshot, progress, interpretation, coachInsight, goalCompletionHandoff, milestones = [] } = narrative;
  return <main className="app-surface mx-auto min-h-screen max-w-[393px] overflow-x-hidden"><div className="px-4 pb-32 pt-10">
    <Link className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-slate-500" href={preview ? "/progress/dexa" : "/briefings/review"}><ArrowLeft size={18}/>{preview ? "DEXA History" : "Briefing History"}</Link>
    <section className="mb-6 space-y-4 rounded-[28px] border border-indigo-100/80 bg-gradient-to-br from-white via-indigo-50/50 to-violet-50/70 p-4 shadow-[0_18px_50px_-30px_rgba(79,70,229,.55)] dark:border-indigo-300/10 dark:from-white/[.07] dark:via-indigo-400/[.05] dark:to-violet-400/[.04]">
      <div className="flex flex-wrap items-center gap-3"><IconBadge color="primary" icon={ScanLine} size="md"/><p className="text-sm font-semibold uppercase tracking-[0.12em] text-indigo-600">DEXA Event Briefing</p>{preview&&<span className="rounded-full bg-amber-100 px-2 py-1 text-[10px] font-black uppercase tracking-wide text-amber-800 dark:bg-amber-400/15 dark:text-amber-200">Preview</span>}</div>
      <h1 className="text-[30px] font-extrabold leading-[1.12] text-slate-950">{hero.title}</h1>
      {hero.confidence&&<BriefingConfidenceAnchor animate confidence={hero.confidence} testId="dexa-v2-confidence" topBorder={false}/>}
      <p className="text-sm font-semibold leading-6 text-slate-600" data-testid="dexa-scan-summary">{hero.body}</p>
      <div className="grid grid-cols-2 gap-2">{hero.results.map((result)=><HeroResult key={result.label} result={result}/>)}</div>
      {milestones.length>0&&<div className="rounded-2xl border border-emerald-200/80 bg-emerald-50/80 p-3 dark:border-emerald-300/15 dark:bg-emerald-300/5"><p className="text-[10px] font-extrabold uppercase tracking-[.1em] text-emerald-700 dark:text-emerald-300">Phase milestone</p><div className="mt-1 space-y-1">{milestones.map((milestone)=><p className="text-sm font-extrabold text-slate-900" key={milestone.id}>{milestone.label}</p>)}</div></div>}
    </section>
    <div className="space-y-3">
      <Card><Eyebrow>Snapshot</Eyebrow><h2 className="mt-1 text-lg font-extrabold">Current scan</h2><div className="mt-3 grid grid-cols-2 gap-2">{[
        ["Date",formatDate(snapshot.scanDate)],["Interval",`${snapshot.daysBetweenScans} days`],["DEXA Weight",`${snapshot.weight.toFixed(1)} lb`],["Body Fat",`${snapshot.bodyFat.toFixed(1)}%`],["Fat Mass",`${snapshot.fatMass.toFixed(1)} lb`],["Lean Tissue",`${snapshot.leanMass.toFixed(1)} lb`],
      ].map(([label,value])=><Metric key={label} label={label} value={value}/>)}</div>{snapshot.rmr!=null&&<p className="mt-3 text-xs font-bold text-slate-500">Estimated RMR: <span className="whitespace-nowrap">{snapshot.rmr.toLocaleString("en-US")} cal/day</span></p>}</Card>
      <Card><Eyebrow>Progress</Eyebrow><h2 className="mt-1 text-lg font-extrabold">What measurably changed</h2>
        <Subheading>Since Last Scan</Subheading><ScanLegend previousDate={narrative.priorScanDate} currentDate={narrative.scanDate}/><div className="mt-2 grid grid-cols-2 gap-2">{progress.headline.map((item)=><Comparison key={item.label} item={item} semantic={item.label==="Lean Tissue"?"lean":"fat"}/>)}</div>
        <Regional title="Regional Fat Change" rows={progress.regionalFat} previousDate={narrative.priorScanDate} currentDate={narrative.scanDate}/>
        <Regional lean title="Measured Lean Tissue Change" rows={progress.regionalLean} previousDate={narrative.priorScanDate} currentDate={narrative.scanDate}/>
        <section className="mt-5 rounded-2xl bg-slate-50/75 p-3 dark:bg-white/[.03]"><Subheading>Other Notable Changes</Subheading><div className="mt-2 space-y-1">{progress.supplemental.map((item)=><SupplementalComparison key={item.label} item={item}/>)}</div></section>
        <div className="mt-6 rounded-[24px] border border-amber-200/70 bg-gradient-to-br from-amber-50/80 via-white to-stone-50 p-1 shadow-[0_20px_42px_-30px_rgba(120,53,15,.55)] dark:border-amber-300/15 dark:from-amber-300/[.06] dark:via-white/[.04] dark:to-stone-300/[.03] [&_.rounded-lg]:rounded-none [&_.rounded-lg]:bg-transparent [&_.rounded-lg]:px-0"><CutTimeline label={progress.timelineLabel} timeline={progress.timeline}/></div>
      </Card>
      <Card><Eyebrow>Interpretation</Eyebrow><h2 className="mt-1 text-lg font-extrabold">What this scan means</h2><p className="mt-2 text-sm font-bold leading-6 text-slate-800">{interpretation.opening}</p><Interpret label={narrative.interpretationLabels?.bodyFat??(narrative.semanticGoalType==="fat_loss"?"Fat loss":"Body-fat guardrail")} value={interpretation.fatLoss}/><Interpret label="Lean tissue" value={interpretation.leanMass}/><Interpret label="Where change occurred" value={interpretation.regional}/>{interpretation.phaseMeaning&&<Interpret label={narrative.interpretationLabels?.strategy??"Phase and strategy"} value={interpretation.phaseMeaning}/>} {interpretation.stoodOut&&<Interpret label="What stood out" value={interpretation.stoodOut}/>}<Interpret label="Supporting context" value={interpretation.supportingEvidence}/><Interpret label={narrative.interpretationLabels?.uncertainty??"Uncertainty"} value={interpretation.uncertainty}/></Card>
      <Card className="border-violet-200/70 bg-violet-50/45 dark:border-violet-300/15 dark:bg-violet-300/[.04]"><p className="text-[10px] font-extrabold uppercase tracking-[.1em] text-violet-700 dark:text-violet-300">Coach’s Insight</p><div className="mt-3 space-y-3"><Coach label={narrative.coachLabels?.biggestWin??"🎉 Biggest Takeaway"} value={coachInsight.biggestWin}/><Coach label={narrative.coachLabels?.protect??"💪 Recommendation"} value={coachInsight.protect}/><Coach label={narrative.coachLabels?.watch??"👀 What to Watch"} value={coachInsight.watch}/><Coach label={narrative.coachLabels?.next??"🎯 Next Actions"} value={coachInsight.next}/></div></Card>
      {phaseReview}
      {goalCompletionHandoff?.actionHref&&<Card className="border-emerald-200/70 bg-emerald-50/50 dark:border-emerald-300/15 dark:bg-emerald-300/[.04]"><Eyebrow>Visual confirmation</Eyebrow><h2 className="mt-1 text-lg font-extrabold">One qualified check remains</h2><p className="mb-4 mt-2 text-sm font-semibold leading-6 text-slate-700">{goalCompletionHandoff.question}</p><ActionButton href={goalCompletionHandoff.actionHref} icon={Camera}>{goalCompletionHandoff.actionLabel}</ActionButton></Card>}
    </div>
  </div></main>;
}

function hasCompleteDexaNarrative(narrative) {
  const snapshot = narrative?.snapshot;
  return Boolean(
    narrative?.hero &&
    narrative?.progress &&
    narrative?.interpretation &&
    narrative?.coachInsight &&
    /^\d{4}-\d{2}-\d{2}$/.test(String(snapshot?.scanDate ?? "")) &&
    ["weight", "bodyFat", "fatMass", "leanMass"].every((field) => Number.isFinite(snapshot?.[field]))
  );
}

function HeroResult({result}){const lean=result.label==="Lean Tissue";const fat=["Fat Mass","Body Fat","Trunk Fat"].includes(result.label);const tone=lean?"border-blue-200/70 bg-blue-100/65 dark:border-blue-300/20 dark:bg-blue-400/[.12]":fat?"border-orange-200/70 bg-orange-100/65 dark:border-orange-300/20 dark:bg-orange-400/[.12]":"border-white/90 bg-white/85 dark:border-white/10 dark:bg-white/[.07]";const semantic=lean?"text-blue-700 dark:text-blue-300":fat?"text-orange-700 dark:text-orange-300":"text-slate-500";const icon=lean?"bg-blue-200/60 dark:bg-blue-300/15":fat?"bg-orange-200/60 dark:bg-orange-300/15":"bg-slate-100 dark:bg-white/10";return <div className={`flex min-h-32 flex-col rounded-2xl border p-3.5 shadow-[0_10px_24px_-18px_rgba(15,23,42,.5)] ${tone}`}><div className="flex items-center gap-1.5"><span aria-hidden className={`rounded-lg p-1 ${icon}`}>{result.emoji}</span><p className={`text-[9px] font-extrabold uppercase tracking-[.09em] ${semantic}`}>{result.label}</p></div><p className="mt-3 text-[25px] font-black leading-none tracking-[-.04em] text-slate-950">{result.value}</p>{result.context&&<p className="mt-auto pt-3 text-[11px] font-bold leading-4 text-slate-500">{result.context}</p>}</div>}
function Metric({label,value}){return <div className="rounded-xl bg-[var(--surface-muted)] p-3"><p className="text-[9px] font-extrabold uppercase tracking-[.08em] text-slate-400">{label}</p><p className="mt-1 text-sm font-extrabold text-slate-700">{value}</p></div>}
function ScanLegend({previousDate,currentDate}){return <div className="mt-2 grid grid-cols-2 gap-2"><ScanIdentity label="Previous" date={previousDate} current={false}/><ScanIdentity label="Current" date={currentDate} current/></div>}
function ScanIdentity({label,date,current}){return <div className={`rounded-xl border px-3 py-2 ${current?"border-indigo-200 bg-indigo-50/70 dark:border-indigo-300/20 dark:bg-indigo-300/5":"border-slate-200 bg-slate-50 dark:border-white/10 dark:bg-white/[.03]"}`}><p className="text-[9px] font-black uppercase tracking-[.08em] text-slate-400">{label}</p><p className="mt-0.5 text-xs font-extrabold text-slate-800">{formatShortDate(date)}</p></div>}
function Comparison({item,semantic}){return <section className="rounded-xl bg-[var(--surface-muted)] p-3"><div className="flex items-start justify-between gap-2"><p className="text-[9px] font-extrabold uppercase tracking-[.08em] text-slate-400">{item.label}</p><span className={`whitespace-nowrap text-sm font-black ${outcomeTone(semantic,item.delta)}`}><Delta item={item}/></span></div><div className="mt-2 grid grid-cols-2 gap-1 text-[10px] font-bold text-slate-500"><span>Previous</span><span>Current</span><strong className="whitespace-nowrap text-xs text-slate-700">{formatValue(item.previous,item.displayUnit,item.precision)}</strong><strong className="whitespace-nowrap text-xs text-slate-900">{formatValue(item.current,item.displayUnit,item.precision)}</strong></div></section>}
function Delta({item}){return <>{item.delta>0?"+":item.delta<0?"−":""}{Math.abs(item.delta).toFixed(item.precision??(item.unit==="pts"?1:1))} {item.unit}</>}
function Regional({lean=false,rows,title,previousDate,currentDate}){const tone=lean?"bg-blue-50/60 dark:bg-blue-300/[.04]":"bg-orange-50/60 dark:bg-orange-300/[.04]";return <section className={`mt-5 rounded-2xl p-3 ${tone}`}><Subheading>{title}</Subheading><p className="mt-1 text-[10px] font-semibold text-slate-500">{formatShortDate(previousDate)} to {formatShortDate(currentDate)}</p><div className="mt-2 space-y-1">{rows.map((item)=><ComparisonRow key={`${lean?"lean":"fat"}-${item.region}`} item={item} semantic={lean?"lean":"fat"}/>)}</div></section>}
// Semantic colors communicate outcomes; neutral colors communicate evidence.
// Previous, current, and delta are read faster as one row than as mini cards.
const comparisonGridColumns="grid-cols-[68px_minmax(0,1fr)_16px_minmax(0,1fr)_64px]";
function ComparisonRow({item,semantic="neutral"}){const compact=item.label==="RMR";return <div aria-label={`${item.label}: previous ${formatTextValue(item.previous,item.displayUnit??item.unit,item.precision??1)}, current ${formatTextValue(item.current,item.displayUnit??item.unit,item.precision??1)}, change ${formatTextValue(item.delta,item.unit,item.precision??1)}`} data-comparison-grid className={`grid ${comparisonGridColumns} items-end gap-x-1 py-2.5`}><p data-comparison-metric className="whitespace-nowrap pb-0.5 text-left text-[11px] font-extrabold leading-4 text-slate-700">{item.label}</p><SmallValue align="right" compact={compact} label="Previous" value={formatValue(item.previous,item.displayUnit??item.unit,item.precision??1)}/><MovementArrow delta={item.delta} semantic={semantic}/><SmallValue align="left" compact={compact} label="Current" value={formatValue(item.current,item.displayUnit??item.unit,item.precision??1)}/><span data-comparison-delta className={`whitespace-nowrap pb-0.5 text-right text-sm font-black leading-4 ${outcomeTone(semantic,item.delta)}`}><Delta item={item}/></span></div>}
function SupplementalComparison({item}){return <ComparisonRow item={item} semantic={item.label==="Visceral Fat"||item.label==="A/G Ratio"?"fat":"neutral"}/>}
function MovementArrow({delta,semantic}){const direction=delta>0?"↑":delta<0?"↓":"→";const desirable=(semantic==="fat"&&delta<0)||(semantic==="lean"&&delta>0);const undesirable=(semantic==="fat"&&delta>0);const tone=desirable?"text-emerald-600 dark:text-emerald-400":undesirable?"text-orange-600 dark:text-orange-400":"text-slate-400";return <span aria-label={`${direction} ${desirable?"desired":undesirable?"watch":"neutral"} movement`} data-movement-arrow className={`flex h-4 w-4 self-end justify-self-center items-center justify-center pb-0.5 text-center text-lg font-black leading-none ${tone}`}>{direction}</span>}
function outcomeTone(semantic,delta){if(delta===0||semantic==="neutral")return "text-slate-600 dark:text-slate-300";return semantic==="lean"?"text-blue-700 dark:text-blue-300":"text-orange-700 dark:text-orange-300"}
function SmallValue({label,value,align,compact=false}){return <div className={`${align==="right"?"items-end text-right":"items-start text-left"} flex min-w-0 flex-col gap-0.5 whitespace-nowrap`}><span data-comparison-label className={`${compact?"text-[7px]":"text-[8px]"} font-black uppercase leading-[10px] tracking-tight text-slate-400`}>{label}</span><span data-comparison-value className={`${compact?"text-[9px] tracking-tight":"text-[10px]"} font-extrabold leading-3 text-slate-800`}>{value}</span></div>}
function CutTimeline({timeline,label="Since Starting This Cut"}){if(!timeline?.available)return <section className="mt-5 p-3"><p className="text-xs font-extrabold uppercase tracking-[.07em] text-amber-700 dark:text-amber-300">{label}</p><p className="mt-2 text-xs font-semibold leading-5 text-slate-500">A defensible goal-phase DEXA baseline is not available.</p></section>;return <section className="rounded-[20px] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-extrabold uppercase tracking-[.07em] text-amber-700 dark:text-amber-300">{label}</p>{timeline.simulated&&<span className="rounded-full bg-amber-100 px-2 py-1 text-[9px] font-black uppercase text-amber-800 dark:bg-amber-300/10 dark:text-amber-200">Simulated</span>}</div><p className="mt-1 text-[10px] font-semibold text-amber-800/70 dark:text-amber-200/60">{timeline.elapsedDays} days · {timeline.scans.length} canonical scans</p><div className="mt-2.5 space-y-2.5">{timeline.metrics.map((metric)=><div key={metric.key}><div className="flex items-center justify-between gap-2"><p className="text-[10px] font-extrabold uppercase tracking-[.08em] text-slate-500">{metric.label}</p><p className={`whitespace-nowrap text-xs font-black ${outcomeTone(metric.key==="leanMass"?"lean":"fat",metric.delta)}`}>{metric.delta>0?"+":metric.delta<0?"−":""}{Math.abs(metric.delta).toFixed(1)} {metric.unit}</p></div><div className="mt-1.5 grid gap-1" style={{gridTemplateColumns:`repeat(${metric.points.length}, minmax(0, 1fr))`}}>{metric.points.map((point,index)=><div className={`rounded-lg px-1.5 py-1.5 text-center ${index===metric.points.length-1?"bg-amber-100/70 dark:bg-amber-300/10":"bg-white/80 dark:bg-white/5"}`} key={point.scanId}><p className="text-[9px] font-bold text-slate-400">{formatShortDate(point.date)}</p><p className="mt-0.5 whitespace-nowrap text-[11px] font-extrabold text-slate-800">{formatValue(point.value,metric.unit,1)}</p></div>)}</div></div>)}</div><p className="mt-2.5 text-xs font-semibold leading-5 text-slate-600">Across this body-composition timeline, body fat moved from {timeline.summary.bodyFat.previous.toFixed(1)}% to {timeline.summary.bodyFat.current.toFixed(1)}%, fat mass changed {signedValue(timeline.summary.fatMass.delta,"lb")}, and measured lean tissue changed {signedValue(timeline.summary.leanMass.delta,"lb")}.</p></section>}
function Interpret({label,value}){return <section className="mt-3 rounded-xl bg-[var(--surface-muted)] p-3"><p className="text-[10px] font-extrabold uppercase tracking-[.08em] text-[var(--primary)]">{label}</p><p className="mt-1 text-xs font-semibold leading-5 text-slate-700">{value}</p></section>}
function Coach({label,value}){return <section><p className="text-[10px] font-extrabold uppercase tracking-[.08em] text-[var(--primary)]">{label}</p><p className="mt-1 text-sm font-semibold leading-6 text-slate-700">{value}</p></section>}
function Eyebrow({children}){return <p className="text-[10px] font-extrabold uppercase tracking-[.1em] text-[var(--primary)]">{children}</p>}
function Subheading({children}){return <p className="mt-4 text-xs font-extrabold uppercase tracking-[.07em] text-slate-900">{children}</p>}
function formatValue(value,unit,precision=unit===""?2:unit==="cal/day"?0:1){if(value==null)return "—";const formatted=Number(value).toFixed(precision);return <>{formatted}{unit==="%"?"%":unit?<> <span>{unit}</span></>:""}</>}
function formatTextValue(value,unit,precision=1){if(value==null)return "—";return `${Number(value).toFixed(precision)}${unit==="%"?"%":unit?` ${unit}`:""}`}
function signedValue(value,unit){return `${value>0?"+":value<0?"−":""}${Math.abs(value).toFixed(1)} ${unit}`}
function formatDate(value){const [y,m,d]=value.split("-").map(Number);return new Date(y,m-1,d).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})}
function formatShortDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value??"")))return "Not available";const [y,m,d]=String(value).split("-").map(Number);return new Date(y,m-1,d).toLocaleDateString("en-US",{month:"short",day:"numeric"})}
